	/* updateMasterMdCdPrimaryActivityDetailRegPop */
		UPDATE KEP_VISITDT A
        SET
	         A.VISIT_DATE = #{st_visit_date}
	        ,A.VISIT_TIME = #{st_visit_time}
	        ,A.VISIT_TYPE = #{st_visit_type}
	        ,A.VISIT_NOTE = #{st_cstmr_remark}
	        ,A.IMAGE_KEY = #{st_image_key}
	        ,A.TO_VISIT_TIME = #{st_visit_to_time}
	        ,A.KEP_CFRC_NM = #{st_kep_rspn_text}
	        ,A.BUYER_CFRC_RM = #{st_cstmr_rspn_text}
	        ,A.CFRC_PALCE = #{st_palce_text}
	WHERE A.BUYER = #{com_code}
	AND A.ADD_DATE = #{add_date}
	AND A.ADD_TIME = #{add_time}
	AND A.STATUS <> 'D'
